import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/data/users.db'
SECRET_HMAC_KEY = os.environ.get('HMAC_SECRET', 'default-key-for-dev')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        password_hash TEXT,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT,
        credit_card_last4 TEXT,
        ssn_encrypted TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        query TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

def verify_session(token):
    """Verify session token using HMAC - note: timing-safe comparison used"""
    if not token:
        return None
    parts = token.split(':')
    if len(parts) != 2:
        return None
    user_id, signature = parts
    expected = hmac.new(SECRET_HMAC_KEY.encode(), user_id.encode(), hashlib.sha256).hexdigest()
    if hmac.compare_digest(signature, expected):
        return user_id
    return None

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('value', '')

    # Whitelist allowed search fields
    allowed_fields = ['username', 'email', 'role', 'id']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid search field'}), 400

    # Log the search for compliance
    db = get_db()

    # Build query - field is validated above so safe to interpolate
    query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    try:
        db.execute("INSERT INTO audit_log (action, query) VALUES (?, ?)",
                   ('search', query))
        db.commit()
    except Exception:
        pass  # Don't fail on audit log issues

    try:
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'results': results, 'count': len(results)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Database error', 'details': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user profile - requires valid session"""
    token = request.headers.get('X-Session-Token')
    authenticated_user = verify_session(token)
    if not authenticated_user:
        return jsonify({'error': 'Unauthorized'}), 401

    db = get_db()
    cursor = db.execute(
        "SELECT id, username, email, role FROM users WHERE id = ?",
        (user_id,)
    )
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.3'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
